package com.google.javascript.jscomp;

import com.google.javascript.Rhino;
import com.google.javascript.jscomp.CheckLevel;
import com.google.javascript.jscomp.NodeTraversal.Callback;
import com.google.javascript.jscomp.errors.CompilerErrorCode;
import com.google.javascript.rhino.JSDocInfo;
import com.google.javascript.rhino.Node;
import com.google.javascript.rhino.Token;
import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.BlockJUnit4ClassRunner;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static com.google.javascript.jscomp.CheckGlobalThis.GLOBAL_THIS;
import static org.junit.Assert.*;
import static org.junit.Assert.assertNull;

@RunWith(BlockJUnit4ClassRunner.class)
public class CheckGlobalThis_visit_TriageGen1Test {

  @Mock private NodeTraversal mockTraversal;
  @Mock private Compiler mockCompiler;
  @Mock private Node mockN;
  @Mock private Node mockParent;
  @Mock private Node mockError;

  private CheckGlobalThis checkGlobalThis;

  @Before
  public void setUp() {
    MockitoAnnotations.openMocks(this);
    checkGlobalThis = new CheckGlobalThis(mockCompiler);
  }

  /**
   * Helper to create a Node with specific type using Rhino's internal logic 
   * if necessary, but mocking is safer for unit testing logic isolation.
   */
  private void setNodeType(Node node, int type) {
    org.mockito.Mockito.when(node.getType()).thenReturn(type);
  }

  @Test
  public void testVisit_ThisAndShouldReportThis_ReportsError() {
    // Arrange
    setNodeType(mockN, Token.THIS);
    // We need to subclass or use spy if shouldReportThis is private/protected 
    // but based on the prompt, we assume we are testing the logic including shouldReportThis.
    // Since we cannot easily mock 'shouldReportThis' if it's a private method of the class under test,
    // we rely on the behavior of the real method. 
    // Assuming shouldReportThis returns true for this setup.
    CheckGlobalThis spyCheck = org.mockito.Mockito.spy(checkGlobalThis);
    org.mockito.Mockito.doReturn(true).when(spyCheck).shouldReportThis(mockN, mockParent);
    org.mockito.Mockito.when(mockTraversal.makeError(mockN, org.mockito.ArgumentMatchers.anyInt(), org.mockito.ArgumentMatchers.eq(GLOBAL_THIS)))
        .thenReturn(mockError);

    // Act
    spyCheck.visit(mockTraversal, mockN, mockParent);

    // Assert
    org.mockito.Mockito.verify(mockCompiler).report(mockError);
  }

  @Test
  public void testVisit_ThisButShouldNotReportThis_NoErrorReport() {
    // Arrange
    setNodeType(mockN, Token.THIS);
    CheckGlobalThis spyCheck = org.mockito.Mockito.spy(checkGlobalThis);
    org.mockito.Mockito.doReturn(false).when(spyCheck).shouldReportThis(mockN, mockParent);

    // Act
    spyCheck.visit(mockTraversal, mockN, mockParent);

    // Assert
    org.mockito.Mockito.verify(mockCompiler, org.mockito.Mockito.never()).report(org.mockito.ArgumentMatchers.any());
  }

  @Test
  public void testVisit_NotThis_NoErrorReport() {
    // Arrange
    setNodeType(mockN, Token.NAME);

    // Act
    checkGlobalThis.visit(mockTraversal, mockN, mockParent);

    // Assert
    org.mockito.Mockito.verify(mockCompiler, org.mockito.Mockito.never()).report(org.mockito.ArgumentMatchers.any());
  }

  @Test
  public void testVisit_IsAssignLhsChild_ResetsAssignLhsChild() throws Exception {
    // Arrange
    // We use reflection to set the private field assignLhsChild since it's internal state
    java.lang.reflect.Field field = CheckGlobalThis.class.getDeclaredField("assignLhsChild");
    field.setAccessible(true);
    field.set(checkGlobalThis, mockN); // Set it to mockN

    // Act
    checkGlobalThis.visit(mockTraversal, mockN, mockParent);

    // Assert
    assertNull("assignLhsChild should be null after visit if n == assignLhsChild", field.get(checkGlobalThis));
  }

  @Test
  public void testVisit_IsNotAssignLhsChild_DoesNotReset() throws Exception {
    // Arrange
    Node otherNode = org.mockito.Mockito.mock(Node.class);
    java.lang.reflect.Field field = CheckGlobalThis.class.getDeclaredField("assignLhsChild");
    field.setAccessible(true);
    field.set(checkGlobalThis, mockN);

    // Act
    checkGlobalThis.visit(mockTraversal, otherNode, mockParent);

    // Assert
    org.junit.Assert.assertEquals(mockN, field.get(checkGlobalThis));
  }
}
